import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"Download and Install","description":"","frontmatter":{},"headers":[],"relativePath":"en/document/install.md","filePath":"en/document/install.md","lastUpdated":1783774350000}`),a={name:`en/document/install.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="download-and-install" tabindex="-1">Download and Install <a class="header-anchor" href="#download-and-install" aria-label="Permalink to “Download and Install”">​</a></h1><h2 id="platform-support" tabindex="-1">Platform Support <a class="header-anchor" href="#platform-support" aria-label="Permalink to “Platform Support”">​</a></h2><p>Official Releases support the following platforms</p><table tabindex="0"><thead><tr><th style="text-align:left;">Platform</th><th style="text-align:left;">Architectures</th></tr></thead><tbody><tr><td style="text-align:left;">Windows <sup><a href="#platform-note-1">[1]</a></sup></td><td style="text-align:left;">x86 / amd64 / arm32 / arm64</td></tr><tr><td style="text-align:left;">macOS</td><td style="text-align:left;">amd64 / arm64</td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;">x86 / amd64 / arm / arm64 / mips64 / mips / ppc64 / s390x / riscv64</td></tr><tr><td style="text-align:left;">FreeBSD</td><td style="text-align:left;">x86 / amd64</td></tr><tr><td style="text-align:left;">OpenBSD</td><td style="text-align:left;">x86 / amd64</td></tr></tbody></table><p><small id="platform-note-1">[1] Windows 7 is no longer officially supported by golang. Xray uses a patched go to provide separately published builds for it; Windows 7 users should use the releases with the <code>-win7</code> suffix.</small></p><p>Xray actively keeps up with golang versions. For minimum OS version support other than win7, please refer to the latest go release notes corresponding to the time of release.</p><p>Builds for amd64 v2/v3 etc. are not provided as some similar projects do, because testing showed no significant performance improvement, and many critical functions already use runtime detection to automatically use extended instruction sets.</p><h2 id="download-xray" tabindex="-1">Download Xray <a class="header-anchor" href="#download-xray" aria-label="Permalink to “Download Xray”">​</a></h2><p>Precompiled binary ZIP archives are available in <a href="https://github.com/xtls/Xray-core/releases" target="_blank" rel="noreferrer">Github Releases</a>.</p><p>Download the archive for your platform and extract it to start using Xray.</p><h2 id="verify-installation-packages" tabindex="-1">Verify Installation Packages <a class="header-anchor" href="#verify-installation-packages" aria-label="Permalink to “Verify Installation Packages”">​</a></h2><p>Xray provides two verification methods:</p><ul><li>SHA1 / SHA256 digests for ZIP archives</li><li>Reproducible builds: please refer to <a href="./../development/intro/compile.html">Compile Xray</a></li></ul><h2 id="windows-installation" tabindex="-1">Windows Installation <a class="header-anchor" href="#windows-installation" aria-label="Permalink to “Windows Installation”">​</a></h2><ul><li>Download the ZIP archive for Windows from <a href="https://github.com/xtls/Xray-core/releases" target="_blank" rel="noreferrer">Github Releases</a>. After extracting it, you will get the executable file <code>xray.exe</code>, which you can then <a href="./command.html">run with command-line arguments</a></li></ul><h2 id="macos-installation" tabindex="-1">macOS Installation <a class="header-anchor" href="#macos-installation" aria-label="Permalink to “macOS Installation”">​</a></h2><ul><li>Download the ZIP archive for macOS from <a href="https://github.com/xtls/Xray-core/releases" target="_blank" rel="noreferrer">Github Releases</a>. After extracting it, you will get the executable file <code>xray</code>, which you can then <a href="./command.html">run with command-line arguments</a></li><li>Install via the <a href="https://brew.sh" target="_blank" rel="noreferrer">Homebrew</a> package manager: <code>brew install xray</code></li><li><a href="https://github.com/N4FA/homebrew-xray" target="_blank" rel="noreferrer">homebrew-xray</a> thanks to <a href="https://github.com/N4FA" target="_blank" rel="noreferrer">@N4FA</a></li></ul><h2 id="linux-installation" tabindex="-1">Linux Installation <a class="header-anchor" href="#linux-installation" aria-label="Permalink to “Linux Installation”">​</a></h2><h3 id="installation-scripts-and-projects" tabindex="-1">Installation Scripts and Projects <a class="header-anchor" href="#installation-scripts-and-projects" aria-label="Permalink to “Installation Scripts and Projects”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Project</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;">Linux Script</td><td style="text-align:left;"><a href="https://github.com/XTLS/Xray-install" target="_blank" rel="noreferrer">XTLS/Xray-install</a> (<strong>Official</strong>)</td><td style="text-align:left;">Officially maintained Linux installation script</td></tr><tr><td style="text-align:left;">Linux Script</td><td style="text-align:left;"><a href="https://github.com/team-cloudchaser/tempest" target="_blank" rel="noreferrer">tempest</a></td><td style="text-align:left;">Supports <a href="https://systemd.io" target="_blank" rel="noreferrer"><code>Systemd</code></a> and <a href="https://github.com/OpenRC/openrc" target="_blank" rel="noreferrer"><code>OpenRC</code></a></td></tr><tr><td style="text-align:left;">One Click</td><td style="text-align:left;"><a href="https://github.com/zxcvos/Xray-script" target="_blank" rel="noreferrer">Xray-REALITY</a></td><td style="text-align:left;">One-click installation solution</td></tr><tr><td style="text-align:left;">One Click</td><td style="text-align:left;"><a href="https://github.com/aleskxyz/reality-ezpz" target="_blank" rel="noreferrer">reality-ezpz</a></td><td style="text-align:left;">One-click installation solution</td></tr><tr><td style="text-align:left;">One Click</td><td style="text-align:left;"><a href="https://github.com/hello-yunshu/Xray_bash_onekey" target="_blank" rel="noreferrer">Xray_bash_onekey</a></td><td style="text-align:left;">One-click installation solution</td></tr><tr><td style="text-align:left;">One Click</td><td style="text-align:left;"><a href="https://github.com/mack-a/v2ray-agent" target="_blank" rel="noreferrer">v2ray-agent</a></td><td style="text-align:left;">One-click installation solution</td></tr><tr><td style="text-align:left;">One Click</td><td style="text-align:left;"><a href="https://github.com/proxysu/ProxySU" target="_blank" rel="noreferrer">ProxySU</a></td><td style="text-align:left;">One-click installation solution</td></tr><tr><td style="text-align:left;">Magisk</td><td style="text-align:left;"><a href="https://github.com/Asterisk4Magisk/Xray4Magisk" target="_blank" rel="noreferrer">Xray4Magisk</a></td><td style="text-align:left;">For Magisk environments</td></tr><tr><td style="text-align:left;">Magisk</td><td style="text-align:left;"><a href="https://github.com/E7KMbb/Xray_For_Magisk" target="_blank" rel="noreferrer">Xray_For_Magisk</a></td><td style="text-align:left;">For Magisk environments</td></tr></tbody></table><h3 id="package-managers-and-distribution-repositories" tabindex="-1">Package Managers and Distribution Repositories <a class="header-anchor" href="#package-managers-and-distribution-repositories" aria-label="Permalink to “Package Managers and Distribution Repositories”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Project</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;">Arch User Repository</td><td style="text-align:left;"><a href="https://wiki.archlinux.org/index.php/AUR_helpers" target="_blank" rel="noreferrer">AUR helpers</a></td><td style="text-align:left;">Taking <a href="https://github.com/Jguer/yay" target="_blank" rel="noreferrer">yay</a> as an example, install with <code>yay -S xray</code></td></tr><tr><td style="text-align:left;">Arch Linux CN</td><td style="text-align:left;"><a href="https://www.archlinuxcn.org/archlinux-cn-repo-and-mirror/" target="_blank" rel="noreferrer">Arch Linux CN repository</a></td><td style="text-align:left;">After adding the repository, install with <code>pacman -S xray</code> as root</td></tr><tr><td style="text-align:left;">Linuxbrew</td><td style="text-align:left;"><a href="https://brew.sh" target="_blank" rel="noreferrer">Homebrew</a></td><td style="text-align:left;">Usage is the same as Homebrew: <code>brew install xray</code></td></tr><tr><td style="text-align:left;">Gentoo Portage</td><td style="text-align:left;"><a href="https://github.com/microcai/gentoo-zh" target="_blank" rel="noreferrer">Gentoo-zh</a></td><td style="text-align:left;">Suitable for Systemd systems; install after adding the Overlay with layman or eselect-repository</td></tr></tbody></table><h2 id="docker-installation" tabindex="-1">Docker Installation <a class="header-anchor" href="#docker-installation" aria-label="Permalink to “Docker Installation”">​</a></h2><p>Two different styles of Docker images are currently provided:</p><ul><li><p><a href="https://ghcr.io/xtls/xray-core" target="_blank" rel="noreferrer">ghcr.io/xtls/xray-core</a> (<strong>Official</strong>)<br> No root privileges, no shell environment, and support for more architectures. It is compiled and built from the official repository with traceability support. It sacrifices convenience in pursuit of more extreme security.</p><details class="details custom-block"><summary>File Structure</summary><ul><li><code>/usr/local/bin/xray</code>: Xray main program (owner: <code>root:root</code>, file permissions: <code>755</code>)</li><li><code>/usr/local/etc/xray/</code>: Configuration file directory (mount point) (owner: <code>root:root</code>, directory permissions: <code>755</code>, file permissions: <code>644</code>) <ul><li>00_log.json</li><li>01_api.json</li><li>02_dns.json</li><li>03_routing.json</li><li>04_policy.json</li><li>05_inbounds.json</li><li>06_outbounds.json</li><li>07_stats.json</li><li>08_fakedns.json</li><li>09_metrics.json</li><li>10_observatory.json</li><li>11_geodata.json</li><li>12_env.json</li><li>99_version.json</li></ul></li><li><code>/usr/local/share/xray/</code>: Resource file directory containing Loyalsoldier geolocation data files (owner: <code>65532:65532</code>, directory permissions: <code>755</code>, file permissions: <code>644</code>) <ul><li>geoip.dat</li><li>geosite.dat</li></ul></li><li><code>/var/log/xray/</code>: Log file directory (mount point) (directory owner: <code>root:root</code>, permissions: <code>755</code>; file owner: <code>65532:65532</code>, permissions: <code>600</code>) <ul><li>access.log</li><li>error.log</li></ul></li></ul></details></li><li><p><a href="https://hub.docker.com/r/teddysun/xray" target="_blank" rel="noreferrer">teddysun/xray</a><br> Has root privileges, includes a shell environment, and is compatible with all architectures supported by Alpine. It is compiled and built by the private server <code>dl.lamp.sh</code>. More convenient to use.</p><details class="details custom-block"><summary>File Structure</summary><ul><li><code>/usr/bin/xray</code>: Xray main program</li><li><code>/etc/xray/config.json</code>: Single configuration file (its parent directory is a mount point)</li><li><code>/usr/share/xray/</code>: Resource file directory containing v2fly geolocation data files <ul><li>geoip.dat</li><li>geosite.dat</li></ul></li></ul></details></li></ul><h2 id="third-party-graphical-clients" tabindex="-1">Third-Party Graphical Clients <a class="header-anchor" href="#third-party-graphical-clients" aria-label="Permalink to “Third-Party Graphical Clients”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Platform</th><th style="text-align:left;">Project</th></tr></thead><tbody><tr><td style="text-align:left;">OpenWrt</td><td style="text-align:left;"><a href="https://github.com/Openwrt-Passwall/openwrt-passwall" target="_blank" rel="noreferrer">PassWall</a></td></tr><tr><td style="text-align:left;">OpenWrt</td><td style="text-align:left;"><a href="https://github.com/Openwrt-Passwall/openwrt-passwall2" target="_blank" rel="noreferrer">PassWall 2</a></td></tr><tr><td style="text-align:left;">OpenWrt</td><td style="text-align:left;"><a href="https://github.com/fw876/helloworld" target="_blank" rel="noreferrer">ShadowSocksR Plus+</a></td></tr><tr><td style="text-align:left;">OpenWrt</td><td style="text-align:left;"><a href="https://github.com/yichya/luci-app-xray" target="_blank" rel="noreferrer">luci-app-xray</a> (<a href="https://github.com/yichya/openwrt-xray" target="_blank" rel="noreferrer">openwrt-xray</a>)</td></tr><tr><td style="text-align:left;">Asuswrt-Merlin</td><td style="text-align:left;"><a href="https://github.com/DanielLavrushin/asuswrt-merlin-xrayui" target="_blank" rel="noreferrer">XRAYUI</a></td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><a href="https://github.com/v2rayA/v2rayA" target="_blank" rel="noreferrer">v2rayA</a></td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><a href="https://github.com/2dust/v2rayN" target="_blank" rel="noreferrer">v2rayN</a></td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><a href="https://github.com/LorenEteval/Furious" target="_blank" rel="noreferrer">Furious</a></td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><a href="https://github.com/InvisibleManVPN/InvisibleMan-XRayClient" target="_blank" rel="noreferrer">Invisible Man - Xray</a></td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><a href="https://github.com/AnyPortal/AnyPortal" target="_blank" rel="noreferrer">AnyPortal</a></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;"><a href="https://github.com/2dust/v2rayNG" target="_blank" rel="noreferrer">v2rayNG</a></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;"><a href="https://github.com/XTLS/X-flutter" target="_blank" rel="noreferrer">X-flutter</a></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;"><a href="https://github.com/SaeedDev94/Xray" target="_blank" rel="noreferrer">SaeedDev94/Xray</a></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;"><a href="https://github.com/lhear/SimpleXray" target="_blank" rel="noreferrer">SimpleXray</a></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;"><a href="https://github.com/AnyPortal/AnyPortal" target="_blank" rel="noreferrer">AnyPortal</a></td></tr><tr><td style="text-align:left;">iOS / macOS arm64 / tvOS</td><td style="text-align:left;"><a href="https://apps.apple.com/app/happ-proxy-utility/id6504287215" target="_blank" rel="noreferrer">Happ</a> (<a href="https://apps.apple.com/us/app/happ-proxy-utility-for-tv/id6748297274" target="_blank" rel="noreferrer">tvOS</a>)</td></tr><tr><td style="text-align:left;">iOS / macOS arm64 / tvOS</td><td style="text-align:left;"><a href="https://apps.apple.com/app/foxray/id6448898396" target="_blank" rel="noreferrer">FoXray</a></td></tr><tr><td style="text-align:left;">iOS / macOS arm64 / tvOS</td><td style="text-align:left;"><a href="https://apps.apple.com/app/streisand/id6450534064" target="_blank" rel="noreferrer">Streisand</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://apps.apple.com/app/happ-proxy-utility/id6504287215" target="_blank" rel="noreferrer">Happ</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/v2rayA/v2rayA" target="_blank" rel="noreferrer">v2rayA</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/2dust/v2rayN" target="_blank" rel="noreferrer">v2rayN</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/yanue/V2rayU" target="_blank" rel="noreferrer">V2rayU</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/tzmax/V2RayXS" target="_blank" rel="noreferrer">V2RayXS</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/LorenEteval/Furious" target="_blank" rel="noreferrer">Furious</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/OneXray/OneXray" target="_blank" rel="noreferrer">OneXray</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/goxray/desktop" target="_blank" rel="noreferrer">GoXRay</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/AnyPortal/AnyPortal" target="_blank" rel="noreferrer">AnyPortal</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/v2rayA/v2rayA" target="_blank" rel="noreferrer">v2rayA</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/2dust/v2rayN" target="_blank" rel="noreferrer">v2rayN</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/LorenEteval/Furious" target="_blank" rel="noreferrer">Furious</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/ketetefid/GorzRay" target="_blank" rel="noreferrer">GorzRay</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/goxray/desktop" target="_blank" rel="noreferrer">GoXRay</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/AnyPortal/AnyPortal" target="_blank" rel="noreferrer">AnyPortal</a></td></tr></tbody></table><h2 id="uuid-generator" tabindex="-1">UUID Generator <a class="header-anchor" href="#uuid-generator" aria-label="Permalink to “UUID Generator”">​</a></h2><p>Third-party UUID generator: <a href="https://www.uuidgenerator.net" target="_blank" rel="noreferrer">uuidgenerator.net</a></p>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};